.nav {
  position: fixed;
  inset: 0 0 auto;
  z-index: 50;
  transition: background 0.3s var(--ease), border-color 0.3s var(--ease);
  border-bottom: 1px solid transparent;
}

.nav.is-scrolled,
.nav {
  background: rgba(8, 8, 8, 0.72);
  border-bottom-color: rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(10px);
}

.nav__bar {
  display: grid;
  grid-template-columns: auto 1fr auto auto;
  align-items: center;
  gap: 1.25rem;
  width: min(100% - 2rem, var(--max));
  height: 3.6rem;
  margin-inline: auto;
}

.nav__brand {
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.nav__links {
  display: none;
  justify-content: center;
  gap: 1.55rem;
}

.nav__links a {
  color: rgba(244, 241, 236, 0.58);
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: color 0.2s ease;
}

.nav__links a:hover {
  color: var(--text);
}

.nav__item {
  position: relative;
}

.nav__submenu {
  position: absolute;
  top: calc(100% + 0.85rem);
  left: 50%;
  min-width: 13.5rem;
  padding: 0.65rem 0;
  background: rgba(12, 12, 12, 0.98);
  border: 1px solid var(--line);
  opacity: 0;
  visibility: hidden;
  transform: translateX(-50%) translateY(6px);
  transition:
    opacity 0.2s ease,
    transform 0.2s ease,
    visibility 0.2s ease;
}

.nav__item:hover .nav__submenu,
.nav__item:focus-within .nav__submenu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.nav__submenu a {
  display: block;
  padding: 0.65rem 1rem;
  white-space: nowrap;
}

.nav__mobile-sub {
  padding-left: 1rem !important;
  font-size: 0.92rem !important;
  color: var(--muted) !important;
  border-bottom-color: transparent !important;
}

.nav__cta {
  display: none;
  min-height: 2.35rem;
  padding: 0.55rem 0.95rem;
  font-size: 0.68rem;
}

.nav__toggle {
  width: 2.5rem;
  height: 2.5rem;
  display: grid;
  place-content: center;
  gap: 0.4rem;
  justify-self: end;
}

.nav__toggle span {
  display: block;
  width: 1.35rem;
  height: 1px;
  background: var(--text);
  transition: transform 0.25s var(--ease);
}

.nav__toggle.is-open span:first-child {
  transform: translateY(2.5px) rotate(45deg);
}

.nav__toggle.is-open span:last-child {
  transform: translateY(-2.5px) rotate(-45deg);
}

.nav__panel {
  display: none;
  border-top: 1px solid var(--line);
  background: rgba(10, 10, 10, 0.98);
}

.nav__panel.is-open {
  display: block;
}

.nav__mobile {
  display: grid;
  gap: 0.25rem;
  padding: 1.25rem var(--pad) 2rem;
}

.nav__mobile a {
  padding: 0.85rem 0;
  border-bottom: 1px solid var(--line);
  font-size: 1.05rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.nav__mobile .btn {
  margin-top: 1rem;
  width: fit-content;
}

@media (min-width: 960px) {
  .nav__links {
    display: flex;
  }

  .nav__cta {
    display: inline-flex;
  }

  .nav__toggle,
  .nav__panel {
    display: none !important;
  }
}

/* --- HERO --- */
.hero {
  --hero-card-w: 100px;
  --hero-card-h: 228px;
  --nav-h: 3.6rem;
  position: relative;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #050505;
  isolation: isolate;
}

.hero__bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    radial-gradient(ellipse 48% 30% at 50% 14%, rgba(255, 255, 255, 0.028), transparent 70%),
    #050505;
}

.hero__bg::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.028;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  pointer-events: none;
}

.hero__intro {
  position: relative;
  z-index: 6;
  width: min(100% - 2rem, 44rem);
  margin: 0 auto;
  padding: calc(var(--nav-h) + 1.7rem) 0 1rem;
  text-align: center;
  display: grid;
  justify-items: center;
}

.hero__intro::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 35%;
  bottom: -2.5rem;
  z-index: -1;
  width: min(46rem, 96vw);
  transform: translateX(-50%);
  background: radial-gradient(ellipse at center, rgba(5, 5, 5, 0.94) 0%, rgba(5, 5, 5, 0.72) 42%, rgba(5, 5, 5, 0.28) 68%, transparent 82%);
  pointer-events: none;
}

.hero__eyebrow {
  margin: 0 0 0.7rem;
  color: var(--gold);
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  opacity: 0;
  transform: translateY(10px);
}

.hero.is-entered .hero__eyebrow {
  opacity: 1;
  transform: none;
  transition:
    opacity 0.5s var(--ease) 0.18s,
    transform 0.5s var(--ease) 0.18s;
}

.hero__title {
  display: grid;
  gap: 0.08rem;
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(2rem, 4.4vw, 3.5rem);
  font-weight: 400;
  line-height: 1.02;
  letter-spacing: -0.03em;
  text-wrap: balance;
}

.hero__title-line {
  display: block;
  overflow: hidden;
}

.hero__title-line > span {
  display: block;
  opacity: 0;
  transform: translateY(110%);
}

.hero.is-entered .hero__title-line > span {
  opacity: 1;
  transform: none;
  transition:
    opacity 0.65s var(--ease),
    transform 0.75s var(--ease);
}

.hero.is-entered .hero__title-line:nth-child(1) > span {
  transition-delay: 0.28s;
}

.hero.is-entered .hero__title-line:nth-child(2) > span {
  transition-delay: 0.4s;
}

.hero__lead {
  max-width: 28rem;
  margin: 0.85rem 0 0;
  color: rgba(244, 241, 236, 0.66);
  font-size: clamp(0.9rem, 1.15vw, 1rem);
  line-height: 1.5;
  opacity: 0;
  transform: translateY(12px);
}

.hero.is-entered .hero__lead {
  opacity: 1;
  transform: none;
  transition:
    opacity 0.55s var(--ease) 0.5s,
    transform 0.55s var(--ease) 0.5s;
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.65rem;
  margin-top: 1.1rem;
  opacity: 0;
  transform: translateY(12px);
}

.hero.is-entered .hero__actions {
  opacity: 1;
  transform: none;
  transition:
    opacity 0.55s var(--ease) 0.62s,
    transform 0.55s var(--ease) 0.62s;
}

.hero__composition {
  position: relative;
  z-index: 5;
  flex: 1;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-height: clamp(390px, 52vh, 520px);
  padding: 3.5rem 0 1.35rem;
}

.material-carousel {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(var(--nav-h) + 4.5rem);
  bottom: 5.5rem;
  z-index: 1;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
  overflow-x: clip;
  contain: layout paint;
  transform: translateY(40px);
  opacity: 0;
  pointer-events: none;
}

.hero.is-entered .material-carousel {
  opacity: 1;
  transform: translateY(12px);
  transition:
    opacity 0.85s var(--ease) 0.7s,
    transform 0.95s var(--ease) 0.7s;
}

.material-carousel__stage {
  position: absolute;
  inset: 0;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
  display: grid;
  place-items: center;
  perspective: 1500px;
  perspective-origin: 50% 48%;
  transform-style: preserve-3d;
}

.material-carousel__ring {
  position: relative;
  width: var(--hero-card-w);
  height: var(--hero-card-h);
  transform-style: preserve-3d;
  will-change: transform;
}

.material-card {
  position: absolute;
  inset: 0;
  width: var(--hero-card-w);
  height: var(--hero-card-h);
  border-radius: 10px;
  overflow: hidden;
  background: #151515;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.4);
  transform-style: preserve-3d;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  will-change: transform, opacity, filter;
}

.material-card__media {
  position: absolute;
  inset: 0;
  background: #1a1a1a;
}

.material-card__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.material-card__meta {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  display: grid;
  gap: 0.05rem;
  padding: 1.15rem 0.5rem 0.45rem;
  background: linear-gradient(180deg, transparent 0%, rgba(5, 5, 5, 0.72) 60%);
}

.material-card__meta span {
  color: rgba(244, 241, 236, 0.42);
  font-size: 0.42rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.material-card__meta strong {
  color: rgba(244, 241, 236, 0.86);
  font-size: 0.54rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.material-showcase {
  position: relative;
  z-index: 4;
  width: min(72vw, 980px);
  margin: 0 auto;
  opacity: 0;
  transform: translateY(28px);
}

.hero.is-entered .material-showcase {
  opacity: 1;
  transform: none;
  transition:
    opacity 0.75s var(--ease) 0.88s,
    transform 0.85s var(--ease) 0.88s;
}

.material-showcase__frame {
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 11px;
  background: #0f0f0f;
  box-shadow:
    0 18px 48px rgba(0, 0, 0, 0.5),
    0 0 0 1px rgba(255, 255, 255, 0.03) inset;
}

.material-showcase__chrome {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 0.7rem;
  min-height: 1.85rem;
  padding: 0.35rem 0.65rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  background: #151515;
}

.material-showcase__dots {
  display: inline-flex;
  gap: 0.28rem;
}

.material-showcase__dots i {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 50%;
  background: #3a3a3a;
  display: block;
}

.material-showcase__dots i:nth-child(1) {
  background: #6b6b6b;
}

.material-showcase__url {
  justify-self: center;
  color: rgba(244, 241, 236, 0.36);
  font-size: 0.6rem;
  letter-spacing: 0.08em;
}

.material-showcase__body {
  padding: 0.55rem 0.6rem 0.6rem;
}

.material-showcase__top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  margin-bottom: 0.45rem;
}

.material-showcase__brand {
  margin: 0;
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.material-showcase__subtitle {
  margin: 0.15rem 0 0;
  color: rgba(244, 241, 236, 0.4);
  font-size: 0.58rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.material-showcase__note {
  margin: 0;
  color: rgba(244, 241, 236, 0.38);
  font-size: 0.58rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.material-showcase__layout {
  display: grid;
  grid-template-columns: 1.4fr 0.9fr;
  gap: 0.45rem;
  height: 168px;
}

.material-showcase__hero,
.material-showcase__tile {
  position: relative;
  overflow: hidden;
  border-radius: 7px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: #171717;
  height: 100%;
}

.material-showcase__side {
  display: grid;
  gap: 0.45rem;
  height: 100%;
}

.material-showcase__hero img,
.material-showcase__tile img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.material-showcase__caption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 1rem 0.65rem 0.5rem;
  background: linear-gradient(180deg, transparent 0%, rgba(0, 0, 0, 0.72) 58%);
}

.material-showcase__caption span,
.material-showcase__tile span {
  color: #fff;
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.material-showcase__tile span {
  position: absolute;
  left: 0.55rem;
  bottom: 0.45rem;
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.7);
}

@media (max-width: 1099px) {
  .hero {
    --hero-card-w: 90px;
    --hero-card-h: 206px;
  }

  .material-carousel {
    width: 100%;
    max-width: 100%;
    bottom: 7rem;
  }

  .material-showcase {
    width: min(78vw, 860px);
  }

  .material-showcase__layout {
    height: 150px;
  }
}

@media (max-width: 767px) {
  .hero {
    --hero-card-w: 74px;
    --hero-card-h: 172px;
  }

  .hero__intro {
    padding: calc(var(--nav-h) + 1.25rem) 0 0.85rem;
  }

  .hero__title {
    font-size: clamp(1.85rem, 7.5vw, 2.5rem);
  }

  .hero__composition {
    min-height: 430px;
    padding: 2.5rem 0 1rem;
  }

  .material-carousel {
    width: 100%;
    max-width: 100%;
    top: calc(var(--nav-h) + 5.5rem);
    bottom: 9.5rem;
  }

  .material-showcase {
    width: min(92vw, 560px);
  }

  .material-showcase__layout {
    grid-template-columns: 1fr;
    height: auto;
  }

  .material-showcase__hero {
    height: 120px;
  }

  .material-showcase__side {
    grid-template-columns: 1fr 1fr;
    height: 84px;
  }

  .material-showcase__url,
  .material-showcase__note {
    display: none;
  }
}

@media (max-width: 479px) {
  .hero {
    --hero-card-w: 62px;
    --hero-card-h: 144px;
  }

  .hero__composition {
    min-height: 400px;
  }

  .material-carousel {
    bottom: 12rem;
  }

  .hero__actions {
    width: 100%;
  }

  .hero__actions .btn {
    flex: 1 1 auto;
  }

  .material-showcase__side {
    grid-template-columns: 1fr;
    height: auto;
  }

  .material-showcase__tile {
    height: 76px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero__eyebrow,
  .hero__title-line > span,
  .hero__lead,
  .hero__actions,
  .material-carousel,
  .material-showcase {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }

  .material-carousel {
    transform: none !important;
  }
