/* --- WHAT WE SUPPLY / MATERIAL SHELF --- */
.supply {
  width: min(100% - 2rem, var(--max));
  max-width: 100%;
  margin: 0 auto;
  padding: clamp(4.5rem, 10vw, 7.5rem) 0 clamp(3.5rem, 8vw, 5.5rem);
  overflow-x: clip;
}

.supply__intro {
  display: grid;
  gap: 0.85rem;
  padding-bottom: 1.35rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  margin-bottom: clamp(2rem, 5vw, 3rem);
}

.supply__lead {
  margin: 0;
  max-width: 36rem;
  color: rgba(196, 165, 116, 0.78);
  font-size: 0.86rem;
  line-height: 1.5;
}

.supply__heading {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(2.8rem, 7vw, 5rem);
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: -0.03em;
  color: var(--gold);
}

.supply__meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem 1.5rem;
  padding-top: 0.35rem;
}

.supply__hint {
  margin: 0;
  color: rgba(244, 241, 236, 0.55);
  font-size: 0.88rem;
}

.supply__shelf-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.65rem 1.25rem;
  margin-bottom: 1rem;
}

.supply__shelf-title {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(1.75rem, 3.5vw, 2.55rem);
  font-weight: 400;
  letter-spacing: -0.02em;
  color: var(--text);
}

.supply__shelf-hint {
  margin: 0;
  color: rgba(244, 241, 236, 0.42);
  font-size: 0.78rem;
}

.supply__shelf-grid {
  display: grid;
  grid-template-columns: 1fr;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: #070707;
}

.shelf-card {
  position: relative;
  min-height: 320px;
  perspective: 1400px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.shelf-card:last-child {
  border-bottom: 0;
}

.shelf-card__inner {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 320px;
  transform-style: preserve-3d;
  transition: transform 0.7s var(--ease);
}

.shelf-card.is-flipped .shelf-card__inner {
  transform: rotateY(180deg);
}

.shelf-card__face {
  position: absolute;
  inset: 0;
  display: grid;
  padding: 1.5rem 1.25rem 1.35rem;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  background: #070707;
}

.shelf-card__face--front {
  grid-template-rows: auto auto 1fr auto;
  justify-items: start;
  text-align: left;
  color: inherit;
  cursor: pointer;
}

.shelf-card__face--back {
  transform: rotateY(180deg);
  grid-template-rows: auto 1fr auto;
  gap: 0.75rem;
}

.shelf-card__icon {
  display: grid;
  place-items: center;
  width: 3.2rem;
  height: 2.4rem;
  margin-bottom: 1.35rem;
  color: var(--gold);
}

.shelf-card__icon svg {
  width: 100%;
  height: 100%;
}

.shelf-card__title {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(1.55rem, 2.4vw, 2rem);
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--text);
}

.shelf-card__summary {
  margin: 0.55rem 0 0;
  color: rgba(244, 241, 236, 0.5);
  font-size: 0.86rem;
}

.shelf-card__cta {
  margin-top: auto;
  padding-top: 1.5rem;
  color: var(--gold);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.shelf-card__back-top {
  padding: 0;
  text-align: left;
  cursor: pointer;
}

.shelf-card__back-top h3 {
  margin: 0;
  font-family: var(--serif);
  font-size: 1.35rem;
  font-weight: 400;
  color: var(--gold);
}

.shelf-card__list {
  display: grid;
  align-content: start;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
  overflow-y: auto;
  max-height: 210px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.28) transparent;
}

.shelf-card__list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.62rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  color: rgba(244, 241, 236, 0.86);
  font-size: 0.84rem;
}

.shelf-card__list li i {
  width: 0.7rem;
  height: 1px;
  background: rgba(244, 241, 236, 0.35);
}

.shelf-card__explore {
  color: var(--gold);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.shelf-card__explore:hover {
  color: #d4b78a;
}

@media (min-width: 720px) {
  .supply__shelf-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .shelf-card {
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  }

  .shelf-card:nth-child(odd) {
    border-right: 1px solid rgba(255, 255, 255, 0.1);
  }

  .shelf-card:nth-child(3),
  .shelf-card:nth-child(4) {
    border-bottom: 0;
  }
}

@media (min-width: 1100px) {
  .supply__shelf-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .shelf-card {
    min-height: 380px;
    border-bottom: 0;
    border-right: 1px solid rgba(255, 255, 255, 0.1);
  }

  .shelf-card:nth-child(odd) {
    border-right: 1px solid rgba(255, 255, 255, 0.1);
  }

  .shelf-card:last-child {
    border-right: 0;
  }

  .shelf-card__inner {
    min-height: 380px;
  }

  .shelf-card__list {
    max-height: 250px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .shelf-card__inner {
    transition: none;
  }
}
.fw-guide {
  width: min(100% - 2rem, var(--max));
  margin: 0 auto;
  padding: clamp(4rem, 9vw, 6.5rem) 0;
  border-top: 1px solid var(--line);
}

.eyebrow--line {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
}

.eyebrow--line::before {
  content: "";
  width: 1.35rem;
  height: 1px;
  background: var(--gold);
}

.fw-guide__head {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  gap: 1.5rem 3rem;
  align-items: end;
  padding-bottom: 1.5rem;
  margin-bottom: 1.75rem;
  border-bottom: 1px solid rgba(196, 165, 116, 0.35);
}

.fw-guide__toolbar {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  margin-bottom: 1.15rem;
}

.fw-guide__strip-label {
  font-family: var(--serif);
  font-size: clamp(1.35rem, 2.4vw, 1.85rem);
  font-weight: 400;
  letter-spacing: -0.01em;
}

.fw-guide__counter {
  color: var(--muted);
  font-size: 0.82rem;
  letter-spacing: 0.12em;
}

.fw-guide__cards {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.85rem;
}

.fw-guide__card {
  display: grid;
  gap: 0.7rem;
  align-content: start;
  min-height: 100%;
  padding: 1.25rem 1.15rem 1.3rem;
  text-align: left;
  background: linear-gradient(180deg, #1a1a1a 0%, #121212 100%);
  border: 1px solid var(--line);
  border-radius: 0.65rem;
  transition:
    border-color 0.25s var(--ease),
    background 0.25s var(--ease),
    transform 0.25s var(--ease);
}

.fw-guide__card:hover,
.fw-guide__card.is-active {
  border-color: var(--gold);
  background: linear-gradient(180deg, #1f1c18 0%, #141210 100%);
}

.fw-guide__icon {
  display: grid;
  place-items: start;
  color: var(--gold);
}

.fw-guide__icon svg {
  width: 2.35rem;
  height: 2.35rem;
}

.fw-guide__card-title {
  font-family: var(--serif);
  font-size: 1.35rem;
  font-weight: 400;
  letter-spacing: -0.01em;
}

.fw-guide__card-copy {
  color: var(--muted);
  font-size: 0.9rem;
  line-height: 1.45;
}

.fw-guide__card-link {
  margin-top: 0.35rem;
  color: var(--gold);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.fw-guide__stage {
  display: grid;
  gap: 0;
  margin-top: 1.5rem;
  background: var(--bg-elevated);
  border: 1px solid var(--line);
  overflow: hidden;
}

.fw-guide__media {
  position: relative;
  min-height: 280px;
  overflow: hidden;
  background: #111;
}

.fw-guide__media img {
  width: 100%;
  height: 100%;
  min-height: 280px;
  object-fit: cover;
  transform: scale(1.03);
  transition: transform 0.9s var(--ease), opacity 0.45s var(--ease);
}

.fw-guide__stage:hover .fw-guide__media img {
  transform: scale(1);
}

.fw-guide__copy {
  display: grid;
  align-content: center;
  gap: 0.9rem;
  padding: 1.75rem 1.4rem 2rem;
}

.fw-guide__stage-num {
  color: var(--gold);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.fw-guide__copy h3 {
  font-family: var(--serif);
  font-size: clamp(2.4rem, 5vw, 3.8rem);
  font-weight: 400;
  line-height: 0.98;
  letter-spacing: -0.02em;
  text-transform: uppercase;
}

.fw-guide__copy p:not(.fw-guide__stage-num) {
  max-width: 28rem;
  color: var(--muted);
  font-size: 1.02rem;
}

.fw-guide__copy .btn {
  width: fit-content;
  margin-top: 0.35rem;
}

@media (max-width: 719px) {
  .fw-guide__head {
    grid-template-columns: 1fr;
  }
}

@media (min-width: 720px) {
  .fw-guide__cards {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (min-width: 960px) {
  .fw-guide__cards {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }

  .fw-guide__stage {
    grid-template-columns: 1.2fr 0.9fr;
    min-height: 460px;
  }

  .fw-guide__media,
  .fw-guide__media img {
    min-height: 100%;
  }

  .fw-guide__copy {
    padding: 2.75rem 2.5rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .fw-guide__media img,
  .fw-guide__card {
    transition: none;
  }
}

