.division {
  width: min(100% - 2rem, var(--max));
  margin: 0 auto;
  padding: clamp(3.5rem, 8vw, 6rem) 0;
}

.division--footwear {
  border-top: 1px solid var(--line);
}

.division--apparel {
  border-top: 1px solid var(--line);
  background: transparent;
}

.division__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.15rem;
}

.division__link {
  display: grid;
  height: 100%;
  background: var(--bg-elevated);
  border: 1px solid var(--line);
  overflow: hidden;
  transition: border-color 0.3s var(--ease);
}

.division__link:hover {
  border-color: rgba(196, 165, 116, 0.45);
}

.division__media {
  position: relative;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: #111;
}

.division__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.7s var(--ease);
}

.division__link:hover .division__media img {
  transform: scale(1.04);
}

.division__meta {
  display: grid;
  gap: 0.45rem;
  padding: 1.2rem 1.15rem 1.35rem;
}

.division__meta h3 {
  font-family: var(--serif);
  font-size: clamp(1.45rem, 2.3vw, 1.85rem);
  font-weight: 400;
  letter-spacing: -0.01em;
}

.division__meta p {
  color: var(--muted);
  font-size: 0.95rem;
}

.division--footwear .division__link {
  border-radius: 0;
}

.division--apparel .division__link {
  background: var(--bg-soft);
}

.division--apparel .division__meta h3 {
  font-style: italic;
}

@media (min-width: 720px) {
  .division__grid--industrial {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .division__grid--industrial .division__item--1,
  .division__grid--industrial .division__item--6 {
    grid-column: span 2;
  }

  .division__grid--industrial .division__item--1 .division__link,
  .division__grid--industrial .division__item--6 .division__link {
    grid-template-columns: 1.4fr 0.9fr;
  }

  .division__grid--industrial .division__item--1 .division__media,
  .division__grid--industrial .division__item--6 .division__media {
    aspect-ratio: auto;
    min-height: 300px;
  }

  .division__grid--industrial .division__item--1 .division__meta,
