/* --- MATERIAL LIBRARY (single auto carousel) --- */
.mlib {
  width: 100%;
  max-width: 100%;
  overflow-x: clip;
  background: #050505;
  border-top: 1px solid rgba(196, 165, 116, 0.14);
  border-bottom: 1px solid rgba(196, 165, 116, 0.14);
  padding: clamp(3.5rem, 8vw, 6.5rem) 0;
}

.mlib__inner {
  width: min(100% - 2rem, var(--max));
  max-width: 100%;
  margin: 0 auto;
  display: grid;
  gap: clamp(1.15rem, 2.4vw, 1.75rem);
  min-width: 0;
}

.mlib__label {
  margin: 0;
  color: var(--gold);
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.mlib__label::after {
  content: "";
  display: block;
  width: 2.75rem;
  height: 1px;
  margin-top: 0.85rem;
  background: rgba(196, 165, 116, 0.55);
}

.mlib__stage {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  min-height: 280px;
  overflow: hidden;
  background: #0a0a0a;
  border: 1px solid rgba(196, 165, 116, 0.2);
}

.mlib__slide {
  position: absolute;
  inset: 0;
  margin: 0;
  opacity: 0;
  transform: scale(1.045);
  transition:
    opacity 0.85s var(--ease),
    transform 0.85s var(--ease);
  pointer-events: none;
}

.mlib__slide.is-active {
  opacity: 1;
  transform: scale(1);
  z-index: 1;
  pointer-events: auto;
}

.mlib__slide:not(.is-active) {
  transform: scale(0.985);
}

.mlib__slide img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.mlib__message {
  max-width: 38rem;
  animation: mlibCopyIn 0.7s var(--ease);
}

.mlib__eyebrow {
  margin: 0 0 0.45rem;
  color: rgba(196, 165, 116, 0.75);
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.18em;
}

.mlib__title {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(1.85rem, 3.8vw, 2.85rem);
  font-weight: 400;
  line-height: 1.08;
  letter-spacing: -0.03em;
  color: var(--text);
  text-transform: uppercase;
}

.mlib__body {
  margin: 0.75rem 0 0;
  color: rgba(244, 241, 236, 0.64);
  font-size: clamp(0.92rem, 1.1vw, 1.02rem);
  line-height: 1.55;
}

.mlib__nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.85rem 1.15rem;
  margin-top: 0.25rem;
}

.mlib__index {
  padding: 0;
  color: rgba(244, 241, 236, 0.35);
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  transition: color 0.3s var(--ease);
}

.mlib__index.is-active {
  color: var(--gold);
}

.mlib__index:hover {
  color: rgba(196, 165, 116, 0.85);
}

.mlib__track {
  position: relative;
  display: block;
  width: min(8.5rem, 32vw);
  height: 1px;
  background: rgba(255, 255, 255, 0.14);
  overflow: hidden;
}

.mlib__track-fill {
  display: block;
  height: 100%;
  width: 0;
  background: var(--gold);
  animation: mlibTrack 3.5s linear forwards;
}

@keyframes mlibCopyIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes mlibTrack {
  from { width: 0%; }
  to { width: 100%; }
}

@media (min-width: 960px) {
  .mlib__stage {
    aspect-ratio: 21 / 9;
    min-height: 420px;
  }
}

@media (max-width: 719px) {
  .mlib__stage {
    aspect-ratio: 4 / 3;
    min-height: 240px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mlib__slide,
  .mlib__message {
    transition: none;
    animation: none;
  }

  .mlib__track-fill {
    animation: none;
    width: 100%;
  }
}
.applications {
  width: min(100% - 2rem, var(--max));
  margin: 0 auto;
  padding: clamp(3.5rem, 8vw, 6rem) 0;
  border-top: 1px solid var(--line);
}

.applications__list {
  display: grid;
  border-top: 1px solid var(--line);
}

.applications__item {
  display: grid;
  grid-template-columns: 3.5rem 1fr;
  gap: 1rem;
  align-items: center;
  padding: 1.25rem 0;
  border-bottom: 1px solid var(--line);
}

.applications__num {
  color: var(--gold);
  font-size: 0.78rem;
  letter-spacing: 0.12em;
}

.applications__name {
  font-family: var(--serif);
  font-size: clamp(1.45rem, 3vw, 2.15rem);
  font-weight: 400;
  letter-spacing: -0.01em;
}

@media (min-width: 900px) {
  .applications__list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 3rem;
  }
}

