.why {
  width: min(100% - 2rem, var(--max));
  margin: 0 auto;
  padding: clamp(3rem, 7vw, 5rem) 0;
}

.why__intro {
  max-width: 18ch;
  margin-bottom: clamp(2rem, 5vw, 3.25rem);
}

.why__list {
  display: grid;
  gap: 0;
  border-top: 1px solid var(--line);
}

.why__item {
  display: grid;
  gap: 0.55rem;
  padding: 1.5rem 0;
  border-bottom: 1px solid var(--line);
}

.why__num {
  color: var(--gold);
  font-size: 0.78rem;
  letter-spacing: 0.12em;
}

.why__item h3 {
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.why__item p {
  max-width: 34rem;
  color: var(--muted);
}

.about-note {
  margin-top: 2.5rem;
  padding: 1.5rem 0 0;
  border-top: 1px solid var(--line);
}

.about-note h3 {
  font-family: var(--serif);
  font-size: 1.7rem;
  font-weight: 400;
}

.about-note p {
  max-width: 40rem;
  margin-top: 0.65rem;
  color: var(--muted);
}

@media (min-width: 900px) {
  .why__list {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    border-top: 0;
  }

  .why__item {
    padding: 0 1.5rem 0 0;
    border-bottom: 0;
    border-right: 1px solid var(--line);
  }

  .why__item:first-child {
    padding-left: 0;
  }

  .why__item:last-child {
    border-right: 0;
    padding-right: 0;
