.inquiry {
  background: var(--bg-soft);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.inquiry > .reveal {
  width: min(100% - 2rem, var(--max));
  margin: 0 auto;
  padding: clamp(4.5rem, 10vw, 7rem) 0;
}

.inquiry__title {
  max-width: 14ch;
  font-family: var(--serif);
  font-size: clamp(2.8rem, 7vw, 5rem);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.03em;
}

.inquiry__body {
  max-width: 36rem;
  margin-top: 1.15rem;
  color: var(--muted);
  font-size: 1.05rem;
}

.inquiry__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem;
