.footer {
  width: min(100% - 2rem, var(--max));
  margin: 0 auto;
  padding: clamp(3rem, 7vw, 4.5rem) 0 2rem;
}

.footer__top {
  display: grid;
  gap: 2.5rem;
  padding-bottom: 2.5rem;
  border-bottom: 1px solid var(--line);
}

.footer__brand {
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.footer__blurb {
  max-width: 24rem;
  margin-top: 0.75rem;
  color: var(--muted);
}

.footer__cols {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.75rem;
}

.footer__heading {
  margin-bottom: 0.85rem;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gold);
}

.footer__cols a {
  display: inline-block;
  padding: 0.3rem 0;
  color: var(--muted);
  font-size: 0.95rem;
  transition: color 0.2s ease;
}

.footer__cols a:hover {
  color: var(--text);
}

.footer__base {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  padding-top: 1.35rem;
  color: var(--muted);
  font-size: 0.85rem;
}

@media (min-width: 900px) {
  .footer__top {
    grid-template-columns: 1.1fr 1fr;
  }

  .footer__cols {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 719px) {
  .section-head {
    grid-template-columns: 1fr;
  }
}

/* --- MATERIAL SCROLL JOURNEY (post-hero) --- */
.material-journey {
  position: relative;
  width: 100%;
  max-width: 100%;
  background: #050505;
  overflow-x: clip;
  overflow-y: visible;
}

.journey-bridge {
  height: clamp(2.5rem, 6vw, 4.5rem);
  background:
    linear-gradient(180deg, rgba(5, 5, 5, 0) 0%, rgba(196, 165, 116, 0.08) 48%, rgba(5, 5, 5, 0) 100%);
}

.journey-chapter {
  position: relative;
  width: 100%;
  max-width: 100%;
  height: 280vh;
  overflow-x: clip;
}

.journey-chapter__sticky {
  position: sticky;
  top: 0;
  width: 100%;
  max-width: 100%;
