  text-transform: uppercase;
}

.dual-spot__heading strong {
  font-family: var(--serif);
  font-size: clamp(2.4rem, 5vw, 3.6rem);
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: -0.03em;
  color: var(--text);
  text-transform: uppercase;
}

.dual-spot__cta {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.65rem;
  padding: 0.7rem 1.15rem;
  border: 1px solid rgba(196, 165, 116, 0.55);
  color: var(--gold);
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transition:
    background 0.3s var(--ease),
    color 0.3s var(--ease),
    border-color 0.3s var(--ease);
}

.dual-spot__face--front:hover .dual-spot__cta {
  background: var(--gold);
  color: #0a0a0a;
  border-color: var(--gold);
}

.dual-spot__face--back {
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 1rem;
  padding: 2rem 1.5rem 1.5rem;
  background: #0a0a0a;
  transform: rotateY(180deg);
  border: 1px solid rgba(196, 165, 116, 0.2);
}

.dual-spot__back-close {
  padding: 0;
  text-align: left;
  cursor: pointer;
}

.dual-spot__back-close h3 {
  margin: 0.35rem 0 0;
  font-family: var(--serif);
  font-size: clamp(2rem, 4vw, 2.8rem);
  font-weight: 400;
  color: var(--gold);
  text-transform: uppercase;
  letter-spacing: -0.02em;
}

.dual-spot__list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.55rem 1.25rem;
  align-content: start;
  margin: 0;
  padding: 1rem 0 0;
  list-style: none;
  border-top: 1px solid rgba(196, 165, 116, 0.22);
}

.dual-spot__list li {
  color: rgba(244, 241, 236, 0.82);
  font-size: 0.86rem;
  letter-spacing: 0.02em;
}

.dual-spot__link {
  justify-self: start;
  color: var(--gold);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.dual-spot__link:hover {
  color: #d4b78a;
}

@media (prefers-reduced-motion: reduce) {
  .dual-spot__inner,
  .dual-spot__face--front img {
    transition: none;
  }
}

/* --- WHY ICONIC CARDS --- */
.why-cards {
  width: min(100% - 2rem, var(--max));
  max-width: 100%;
  margin: 0 auto;
  padding: clamp(4.5rem, 10vw, 7.5rem) 0;
  overflow-x: clip;
}

.why-cards__head {
  text-align: center;
  margin-bottom: clamp(2.25rem, 5vw, 3.5rem);
}

.why-cards__title {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(2.6rem, 6vw, 4.25rem);
  font-weight: 400;
  letter-spacing: -0.03em;
  color: #ffffff;
}

.why-cards__grid {
  display: grid;
  gap: 1.25rem;
  grid-template-columns: 1fr;
}

.why-cards__card:nth-child(1) { transition-delay: 0.05s; }
.why-cards__card:nth-child(2) { transition-delay: 0.12s; }
.why-cards__card:nth-child(3) { transition-delay: 0.19s; }

.why-cards__card {
  position: relative;
  display: grid;
  justify-items: center;
  text-align: center;
  gap: 0.95rem;
  padding: clamp(2rem, 4vw, 2.75rem) clamp(1.35rem, 3vw, 2rem);
  background: #161616;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  transition:
    transform 0.45s var(--ease),
    border-color 0.45s var(--ease),
    background 0.45s var(--ease),
    box-shadow 0.45s var(--ease);
}

.why-cards__icon {
  display: grid;
  place-items: center;
  width: 2.8rem;
  height: 2.8rem;
  margin-bottom: 0.15rem;
  transition: transform 0.45s var(--ease);
}

.why-cards__icon svg {
  width: 100%;
  height: 100%;
}

.why-cards__card h3 {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(1.55rem, 2.5vw, 1.95rem);
  font-weight: 400;
  letter-spacing: -0.02em;
  color: #ffffff;
}

.why-cards__card p {
  margin: 0;
  max-width: 28rem;
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.96rem;
  line-height: 1.65;
}

.why-cards__card:hover,
.why-cards__card:focus-within {
  transform: translateY(-6px);
  border-color: rgba(196, 165, 116, 0.4);
  background: #1a1a1a;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.35);
}

.why-cards__card:hover .why-cards__icon,
.why-cards__card:focus-within .why-cards__icon {
  transform: translateY(-2px) scale(1.06);
}

@media (min-width: 900px) {
  .why-cards__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 1.35rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .why-cards__card,
  .why-cards__icon {
    transition: none;
  }

  .why-cards__card:hover,
  .why-cards__card:focus-within {
    transform: none;
  }
}
